import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';
import ClienteList from './components/ClienteList';
import CreateCliente from './components/CreateCliente';
import ProjetoList from './components/ProjetoList';
import CreateProjeto from './components/CreateProjeto';
import AtividadeList from './components/AtividadeList';  
import CreateAtividade from './components/CreateAtividade';

const App = () => {
  const [clientes, setClientes] = useState([]);
  const [projetos, setProjetos] = useState([]);
  const [atividades, setAtividades] = useState([]);
  const [selectedClienteId, setSelectedClienteId] = useState(null);
  const [selectedProjetoId, setSelectedProjetoId] = useState(null);


  useEffect(() => {
    axios.get('http://localhost:8080/clientes')
      .then(response => {
        setClientes(response.data);
      })
      .catch(error => {
        console.error('Erro ao carregar os clientes:', error);
      });
  }, []);

  useEffect(() => {
    if (selectedClienteId) {
      axios.get(`http://localhost:8080/clientes/${selectedClienteId}/projetos`)
        .then(response => {
          setProjetos(response.data);
        })
        .catch(error => {
          console.error('Erro ao carregar os projetos:', error);
        });
    }
  }, [selectedClienteId]);

  // Carregar atividades do projeto selecionado
  useEffect(() => {
    if (selectedClienteId && selectedProjetoId) {
      axios.get(`http://localhost:8080/clientes/${selectedClienteId}/projetos/${selectedProjetoId}/atividades`)
        .then(response => {
          setAtividades(response.data);
        })
        .catch(error => {
          console.error('Erro ao carregar as atividades:', error);
        });
    }
  }, [selectedClienteId, selectedProjetoId]);

  return (
    <div className="container">
      <h1>Gestão de Clientes</h1>
      <CreateCliente onCreate={setClientes} />
      <ClienteList clientes={clientes} setSelectedClienteId={setSelectedClienteId} />

      {selectedClienteId && (
        <div>
          <h2>Projetos do Cliente</h2>
          <ProjetoList
            clienteId={selectedClienteId}
            projetos={projetos}
            setSelectedProjetoId={setSelectedProjetoId}
          />
          <CreateProjeto clienteId={selectedClienteId} />

          {selectedProjetoId && (
            <div>
              <h2>Atividades do Projeto</h2>
              <AtividadeList
                clienteId={selectedClienteId}
                projetoId={selectedProjetoId}
                atividades={atividades}
              />
              <CreateAtividade clienteId={selectedClienteId} projetoId={selectedProjetoId} />
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default App;
